// Normalise Porter's quote into the shape the WING'D site expects:
//   { serviceable: boolean, fare: number, eta: number|null }
// Adjust the field names once you can see a real Porter response.
const r = $input.first().json || {};
const fare = r.fare ?? r.estimated_fare ?? r.total_fare
          ?? (r.vehicles && r.vehicles[0] && r.vehicles[0].fare && r.vehicles[0].fare.minor_amount / 100);
const serviceable = r.serviceable !== false && typeof fare === 'number' && isFinite(fare);
return [{ json: {
  serviceable,
  fare: serviceable ? Math.round(fare) : null,
  eta: r.eta ?? r.eta_minutes ?? null,
  reason: serviceable ? null : (r.reason || 'Not serviceable'),
  raw: r
}}];

// Normalise Porter's create-order response into:
//   { order_id, tracking_url, status }
const r = $input.first().json || {};
const id  = r.order_id ?? r.id ?? r.crn ?? null;
const url = r.tracking_url ?? r.track_url ?? r.tracking_link ?? null;
if (!id) { throw new Error('Porter did not return an order id: ' + JSON.stringify(r).slice(0, 400)); }
return [{ json: { order_id: id, tracking_url: url, status: r.status || 'created', raw: r } }];

// Porter fires this on Accepted, Live, Ended, Reopened and Cancelled.
// Log it, and optionally notify the store on the stages that matter.
const b = $input.first().json.body || {};
return [{ json: { order_id: b.order_id ?? b.crn ?? null, status: b.status ?? b.event ?? null, at: new Date().toISOString(), raw: b } }];
